parameters.jsCode:
// Turn the Error Trigger payload into a Slack message and a dead_letter row.
// Read the Error Trigger by name: the node right before this one is Config, whose output is not the error.
const data = $('Error Trigger').first().json;
// If the database is down, Config has no "cfg": fall back to a default channel so the alert still goes out.
const cfg = $('Config').first().json.cfg ?? {};

const workflowName = data.workflow?.name ?? 'unknown workflow';
const node = data.execution?.lastNodeExecuted ?? 'unknown node';
const error = data.execution?.error?.message ?? 'no error message';
const url = data.execution?.url ?? '';

const text = [
  ':rotating_light: *Workflow failed*',
  `*Workflow:* ${workflowName}`,
  `*Failed node:* ${node}`,
  `*Error:* ${error}`,
  url ? `*Execution:* ${url}` : '',
].filter(Boolean).join('\n');

return [{
  json: {
    workflow: workflowName,
    node,
    error,
    text,
    channel: cfg.slack_channel_alerts ?? '#automation-alerts',
    // What we know about the failed run. n8n does not hand the last node's input to the Error Trigger.
    payload: {
      execution_id: String(data.execution?.id ?? ''),
      execution_url: url,
      mode: data.execution?.mode ?? null,
      stack: data.execution?.error?.stack ?? null,
    },
  },
}];

parameters.query:
INSERT INTO dead_letter (workflow, node, payload, error)
SELECT $1, $2, $3::jsonb, $4
WHERE NOT EXISTS (
  SELECT 1 FROM dead_letter WHERE payload->>'execution_id' = $5
)
RETURNING id;
